package com.huy.enterprise.order; import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.PurchaseOrderStatus; import com.huy.enterprise.product.ProductRepository; import com.huy.enterprise.supplier.SupplierRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*; @Service @RequiredArgsConstructor @Transactional(readOnly=true) public class PurchaseOrderService {private final PurchaseOrderRepository repo;private final SupplierRepository suppliers;private final ProductRepository products; PurchaseOrder entity(UUID id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Purchase order not found: "+id));}public List<OrderResponse> all(){return repo.findAll().stream().map(OrderResponse::from).toList();}public OrderResponse get(UUID id){return OrderResponse.from(entity(id));}@Transactional public OrderResponse save(UUID id,OrderRequest r){if(id==null&&repo.existsByOrderCode(r.orderCode()))throw new ConflictException("Order code already exists");var o=id==null?new PurchaseOrder():entity(id);o.setOrderCode(r.orderCode());o.setSupplier(suppliers.findById(r.supplierId()).orElseThrow(()->new ResourceNotFoundException("Supplier not found: "+r.supplierId())));o.setOrderDate(r.orderDate());o.setExpectedDeliveryDate(r.expectedDeliveryDate());o.setNotes(r.notes());o.getItems().clear();BigDecimal total=BigDecimal.ZERO;for(var x:r.items()){var i=new PurchaseOrderItem();i.setPurchaseOrder(o);i.setProduct(products.findById(x.productId()).orElseThrow(()->new ResourceNotFoundException("Product not found: "+x.productId())));i.setQuantity(x.quantity());i.setUnitPrice(x.unitPrice());i.setLineTotal(x.quantity().multiply(x.unitPrice()));total=total.add(i.getLineTotal());o.getItems().add(i);}o.setTotalAmount(total);return OrderResponse.from(repo.save(o));}@Transactional public OrderResponse status(UUID id,OrderStatusRequest r){var o=entity(id);o.setStatus(r.status());return OrderResponse.from(repo.save(o));}}
